import {scenarios} from './experiment.js?v=20261003h';
import {parseScenario,serializeScenario,ruleDescriptions} from './scenario-format.js?v=20261003h';
import {builtInScenarioIds,scenarioUrl} from './scenario-links.js?v=20261003h';
const storageKey='bus-lab-custom-scenarios-v1';
export function loadCustomPresets(){
  try{const saved=JSON.parse(localStorage.getItem(storageKey)||'[]');if(!Array.isArray(saved)||saved.length>100)return;for(const item of saved){try{const s=parseScenario(item.text);if(typeof item.id!=='string'||!/^custom-[a-f0-9-]+$/.test(item.id))continue;s.id=item.id;s.custom=true;scenarios.push(s);}catch{}}}catch{}
}
export function setupScenarioLibrary(getExperiment){
  const library=document.querySelector('.scenario-panel'),select=document.getElementById('scenario');
  function refresh(){const value=getExperiment().scenarioId;select.replaceChildren();for(const s of scenarios){const option=document.createElement('option');option.value=s.id;option.textContent=(s.custom?'Custom · ':'')+s.name;select.append(option);}select.value=value;}
  refresh();
  const linkButton=document.createElement('button');linkButton.type='button';linkButton.id='copyScenarioLink';linkButton.textContent='Copy scenario link';
  const linkStatus=document.createElement('p');linkStatus.className='hint';linkStatus.id='scenarioLinkStatus';linkStatus.setAttribute('role','status');linkStatus.setAttribute('aria-live','polite');
  library.insertBefore(linkButton,document.getElementById('scenarioDescription'));library.append(linkStatus);
  function updateLink(){linkButton.disabled=!builtInScenarioIds.includes(select.value);linkStatus.textContent=linkButton.disabled?'Custom presets: use Export scenario to share the setup.':'';}
  select.addEventListener('change',updateLink);updateLink();
  linkButton.onclick=async()=>{try{const url=scenarioUrl(location.href,select.value);try{await navigator.clipboard.writeText(url);linkStatus.textContent='Scenario link copied. Opens the selected built-in preset, paused at time zero.';}catch{linkStatus.replaceChildren('Copy this scenario link: ');const input=document.createElement('input');input.readOnly=true;input.value=url;input.setAttribute('aria-label','Scenario link');linkStatus.append(input);input.focus();input.select();}}catch(e){linkStatus.textContent=e.message;}};
  const dialog=document.createElement('dialog');dialog.className='scenario-dialog';dialog.setAttribute('aria-labelledby','scenarioDialogTitle');
  dialog.innerHTML='<div class="dialog-heading"><h2 id="scenarioDialogTitle"></h2><button type="button" id="closeScenarioDialog" aria-label="Close scenario text">×</button></div><p id="scenarioTextHelp"></p><label for="scenarioText">Scenario text</label><textarea id="scenarioText" spellcheck="false"></textarea><details class="format-guide"><summary>Text format & recovery-rule reference</summary><p>This is JSON: keep field names and quotes, use numbers without quotes, and avoid trailing commas. Edit name and description for your lesson. Times are seconds from time zero; bus numbers start at 1. Actions: hold uses seconds, slow uses multiplier (1–10), express uses stops. Events at the same time run in listed order. The setup and seed reproduce arrivals. Imports support up to 1,000 interventions and a seven-day schedule.</p><p>Ideal gap = stops ÷ buses. Forward gap is the distance to the nearest bus ahead, in stop units. recovery_policy can be null, or specify a versioned rule and start_seconds, end_seconds (inclusive), and check_every_seconds. The rule defines the following exact behavior:</p><div id="ruleReference"></div><p>Scenarios start empty with evenly spaced buses. Export includes all preset events and manual interventions recorded in the current run, including later events retained while reviewing history. It excludes current passengers, observations, chart settings, playback speed, and page layout. Imported presets are saved in this browser; keep exported text to share or back up.</p></details><p id="scenarioTextMessage" role="status" aria-live="polite"></p><div class="dialog-actions"><button type="button" id="copyScenarioText">Copy text</button><button type="button" id="saveScenarioText" class="primary">Save as preset</button></div>';
  document.body.append(dialog);const textarea=dialog.querySelector('textarea'),message=dialog.querySelector('#scenarioTextMessage'),save=dialog.querySelector('#saveScenarioText'),copy=dialog.querySelector('#copyScenarioText');
  for(const [rule,description] of Object.entries(ruleDescriptions)){const p=document.createElement('p'),strong=document.createElement('strong');strong.textContent=rule+': ';p.append(strong,description);dialog.querySelector('#ruleReference').append(p);}
  let opener;
  function close(){dialog.close();opener?.focus();}dialog.querySelector('#closeScenarioDialog').onclick=close;dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();}});
  function open(mode,button){opener=button;const exporting=mode==='export';dialog.querySelector('h2').textContent=exporting?'Export scenario':'Import scenario';dialog.querySelector('#scenarioTextHelp').textContent=exporting?'Copy this complete text to share a reproducible lesson. You can edit its name and description before sharing.':'Paste the complete exported text. Saving adds a custom preset; it does not replace your current run.';textarea.value=exporting?serializeScenario(getExperiment().definition,getExperiment().config,getExperiment().commands):'';message.textContent='';save.hidden=exporting;copy.hidden=!exporting;dialog.showModal();textarea.focus();textarea.setSelectionRange(0,0);textarea.scrollTop=0;}
  for(const [mode,label] of [['export','Export scenario'],['import','Import scenario']]){const button=document.createElement('button');button.type='button';button.id=mode+'Scenario';button.textContent=label;button.onclick=()=>open(mode,button);library.insertBefore(button,document.getElementById('scenarioDescription'));}
  copy.onclick=async()=>{try{await navigator.clipboard.writeText(textarea.value);message.textContent='Scenario text copied.';}catch{textarea.focus();textarea.select();message.textContent='Text selected. Use your device’s Copy command.';}};
  save.onclick=()=>{try{const scenario=parseScenario(textarea.value);const custom=scenarios.filter(s=>s.custom);if(custom.length>=100)throw Error('This browser already has 100 custom presets.');scenario.id='custom-'+crypto.randomUUID();scenario.custom=true;const saved=[...custom,scenario].map(s=>({id:s.id,text:serializeScenario(s,s.config)}));try{localStorage.setItem(storageKey,JSON.stringify(saved));}catch{throw Error('Unable to save in this browser. Browser storage may be full or disabled. Keep the text and try another browser.');}scenarios.push(scenario);refresh();select.value=scenario.id;updateLink();message.textContent=`Saved “${scenario.name}”. Close this panel, then choose Load scenario & reset to run it.`;save.disabled=true;}catch(e){message.textContent=e.message;}};
  textarea.addEventListener('input',()=>{save.disabled=false;message.textContent='';});dialog.addEventListener('close',()=>{save.disabled=false;});
}
